therwise stated; no assessment questions reproduced.","reviewedOn":"2026-09-13"},{"id":"english-profile","title":"English Profile: what the CEFR means for English","publisher":"English Profile","url":"https://englishprofile.org/","use":"Level interpretation background. Labels are approximate course labels, not an English Grammar Profile item-by-item validation or a CEFR certification.","reviewedOn":"2026-09-13"},{"id":"cambridge-comprehensive-scope","title":"The Cambridge Grammar of the English Language: contents","publisher":"Cambridge University Press","url":"https://www.cambridge.org/features/linguistics/cgel/contents.htm","use":"Published subject-area crosswalk only. Original learner explanations; no textbook chapter or exercise reproduced. The crosswalk is not publisher approval.","reviewedOn":"2026-09-13"},{"id":"cambridge-spoken","title":"Spoken English","publisher":"Cambridge English Grammar Today","url":"https://dictionary.cambridge.org/grammar/british-grammar/spoken-english","use":"Guidance on spoken grammatical structures; original explanations and examples.","reviewedOn":"2026-09-13"},{"id":"cambridge-hedges","title":"Hedges","publisher":"Cambridge English Grammar Today","url":"https://dictionary.cambridge.org/grammar/british-grammar/hedges-just","use":"Guidance on softening and stance; original explanations and examples.","reviewedOn":"2026-09-13"},{"id":"cambridge-headers-tails","title":"Headers and tails","publisher":"Cambridge English Grammar Today","url":"https://dictionary.cambridge.org/grammar/british-grammar/headers-and-tails","use":"Guidance on spoken information structure; original explanations and examples.","reviewedOn":"2026-09-13"},{"id":"cambridge-negation","title":"Negation","publisher":"Cambridge English Grammar Today","url":"https://dictionary.cambridge.org/grammar/british-grammar/negation_2","use":"Guidance on negative constructions; original explanations and examples.","reviewedOn":"2026-09-13"},{"id":"cambridge-word-formation","title":"Word formation","publisher":"Cambridge English Grammar Today","url":"https://dictionary.cambridge.org/us/grammar/british-grammar/word-formation","use":"Scope and terminology for morphological processes; original explanations and examples.","reviewedOn":"2026-09-13"},{"id":"cambridge-nonfinite-scope","title":"Non-finite and verbless clauses: chapter contents","publisher":"Cambridge University Press","url":"https://www.cambridge.org/assets/linguistics/cgel/chap14_contents.pdf","use":"Published subtopic crosswalk only; original learner explanations and examples.","reviewedOn":"2026-09-13"}]'::jsonb AS items)
SELECT e.slug,(t.payload_md5=e.hash AND t.catalog_hash='87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d') AS payload_matches,
 jsonb_array_length(t.payload->'quizItems') AS questions,
 CASE WHEN t.payload->'provenance'->>'version'='core-2026-09-v4' THEN
 COALESCE((to_jsonb(n)-'created_at'-'updated_at') = jsonb_build_object(
 'slug',t.payload->'slug','title',t.payload->'title','level',t.payload->'level','order_index',t.payload->'order',
 'summary',t.payload->'summary','guidance',t.payload->'guidance','learning_goals',t.payload->'learningGoals',
 'rules',t.payload->'rules','tips',t.payload->'tips','source','seed',
 'source_metadata',(t.payload->'provenance')||jsonb_build_object('contentHash','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d','sources',
 (SELECT jsonb_agg(s) FROM sources CROSS JOIN LATERAL jsonb_array_elements(items) s WHERE t.payload->'provenance'->'referenceIds' ? (s->>'id')))),false) END AS normalized_topic_matches,
 CASE WHEN t.payload->'provenance'->>'version'='core-2026-09-v4' THEN
 (SELECT count(*) FROM jsonb_array_elements(t.payload->'quizItems') q
 JOIN grammar.grammar_quiz_items n ON n.id=(q->>'id')::uuid
 WHERE (to_jsonb(n)-'created_at'-'updated_at'-'content_hash') = jsonb_build_object(
 'id',q->'id','topic_slug',q->'topicSlug','level',q->'level','prompt',q->'prompt',
 'choices',q->'choices','answer_id',q->'answerId','hint',q->'hint','explanation',q->'explanation',
 'keywords',q->'keywords','source','seed','fingerprint',q->'fingerprint',
 'source_metadata',(q->'provenance')||jsonb_build_object('contentHash','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d','skill',q->'skill','contextKey',q->'contextKey','teaching',q->'teaching'))) END AS normalized_questions_matching
FROM expected e LEFT JOIN grammar.content_catalog_topics t ON t.slug=e.slug AND t.version='core-2026-09-v4'
LEFT JOIN grammar.grammar_topics n ON n.slug=e.slug ORDER BY e.slug;
